{"command":"python3 - <<'PY'
N=15
B={(5,6),(6,6),(6,7),(8,7),(8,8),(9,7)}
W={(5,5),(7,6),(7,7),(7,8),(9,9),(10,8)}
board=[['.' for _ in range(N)] for __ in range(N)]
for r,c in B: board[r][c]='B'
for r,c in W: board[r][c]='W'
for r in range(N): print(f'{r:2d}', ''.join(board[r]))
DIRS=[(0,1),(1,0),(1,1),(1,-1)]

def max_run_after(color, move):
    r,c=move
    best=0; details=[]
    stones=B if color=='B' else W
    occ=stones|{move}
    for dr,dc in DIRS:
        cnt=1
        rr,cc=r+dr,c+dc
        while (rr,cc) in occ:
            cnt+=1; rr+=dr; cc+=dc
        rr,cc=r-dr,c-dc
        while (rr,cc) in occ:
            cnt+=1; rr-=dr; cc-=dc
        details.append(((dr,dc),cnt))
        best=max(best,cnt)
    return best, details

empties=[(r,c) for r in range(N) for c in range(N) if board[r][c]=='.']
print('\nImmediate winning moves:')
for color in 'BW':
    wins=[]
    for m in empties:
        if max_run_after(color,m)[0]>=5:
            wins.append((m,max_run_after(color,m)[1]))
    print(color, wins)

# windows with 4 or 3 white and rest empty, no black
print('\nWhite windows with 4/3 and empty completions:')
for k in [4,3]:
    print('k=',k)
    seen=set()
    for r in range(N):
      for c in range(N):
       for dr,dc in DIRS:
        cells=[(r+i*dr,c+i*dc) for i in range(5)]
        if all(0<=rr<N and 0<=cc<N for rr,cc in cells):
          vals=[board[rr][cc] for rr,cc in cells]
          if vals.count('W')==k and vals.count('B')==0:
            empt=[cells[i] for i,v in enumerate(vals) if v=='.']
            key=tuple(cells)
            if key not in seen:
              seen.add(key); print(cells, vals, 'empties', empt)

# rank empty moves by making black runs and blocking white runs
print('\nTop candidate moves')
for m in [(7,5),(7,9),(6,5),(8,9),(9,8),(10,10)]:
    print(m, 'B after', max_run_after('B',m), 'W after', max_run_after('W',m))
